<main class="page narrow" id="main"><section class="auth-card"><div class="status-icon"><?=ui_icon($a['status']==='approved'?'check':($a['status']==='pending'?'clock':'alert'))?></div><span class="chip <?=$a['status']==='pending'?'pending':''?>"><?=e(t(ucfirst($a['status'])))?></span><h1><?=$a['status']==='approved'?t('Welcome to the kitchen.'):($a['status']==='pending'?t('Your profile is under review.'):t('A few details need attention.'))?></h1><p><strong><?=e($a['business_name'])?></strong><br><?=e(t('Submitted'))?> <?=e(local_time($a['submitted_at']))?></p><?php if($a['status']==='pending'): ?><p><?=e(t('Our admin will review your business and CNIC details. We’ll email you once there’s a decision. You can continue browsing as a customer.'))?></p><a class="pill primary" href="<?=e(url())?>"><?=e(t('Explore food →'))?></a><?php elseif($a['status']==='approved'): ?><p><?=e(t('Your business is approved. You can now create your menu.'))?></p><a class="pill primary" href="<?=e(url('seller/index.php'))?>"><?=e(t('Open seller workspace →'))?></a><?php else: ?><div class="alert error"><?=e($a['review_note'])?></div><a class="pill primary" href="<?=e(url('seller/apply.php'))?>"><?=e(t('Update and resubmit'))?></a><?php endif ?></section></main><?php require ROOT.'/app/footer.php'; ?>
